import{c as t,Q as r,j as l,m as i}from"./chunks/framework.BPKcPtvA.js";const e="/images/class-BnsurEbtsBwqzAd.jpg",u=JSON.parse('{"title":"弓箭手攻略 - 技能加点/转职/练级","description":"RO3 弓箭手 1-99 级技能加点、转职任务、练级路线、挂机指南","frontmatter":{"title":"弓箭手攻略 - 技能加点/转职/练级","description":"RO3 弓箭手 1-99 级技能加点、转职任务、练级路线、挂机指南"},"headers":[],"relativePath":"jobs/archer.md","filePath":"jobs/archer.md","lastUpdated":1780230058000}'),o={name:"jobs/archer.md"};function s(n,a,h,d,c,p){return r(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="弓箭手-推荐挂机党-新手" tabindex="-1">弓箭手（推荐挂机党/新手） <a class="header-anchor" href="#弓箭手-推荐挂机党-新手" aria-label="Permalink to &quot;弓箭手（推荐挂机党/新手）&quot;">​</a></h1><p><img src="'+e+'" alt="RO3 弓箭手职业立绘"></p><p>弓箭手是远程物理输出职业，练级时几乎不耗血不耗蓝，是挂机党的首选。适合多开挂机玩家。</p><h2 id="技能加点" tabindex="-1">技能加点 <a class="header-anchor" href="#技能加点" aria-label="Permalink to &quot;技能加点&quot;">​</a></h2><p><strong>1-10 级</strong>：点满「箭术修炼」（加普攻伤害），「鹗枭之眼」点满（加射程，风筝核心）</p><p><strong>11-30 级</strong>：点满「二连矢」（核心输出），「冲锋箭」点 5 级（击退+控制）</p><p><strong>31-60 级</strong>：点满「冲锋箭」，「闪电冲击」点满（群攻技能），「定位陷阱」点 5 级（控怪用）</p><p><strong>61-99 级</strong>：点满「狙杀瞄准」（加暴击和命中），「箭雨」点满（范围输出），剩余点「风之步」（加回避）</p><h2 id="转职任务流程-20级转职" tabindex="-1">转职任务流程（20级转职） <a class="header-anchor" href="#转职任务流程-20级转职" aria-label="Permalink to &quot;转职任务流程（20级转职）&quot;">​</a></h2><ol><li>斐杨找「弓箭手公会会长」（坐标 50,70），接取任务</li><li>击打斐杨树林的靶子 5 个（坐标 30,40 附近分布）</li><li>去斐杨森林收集 10 个「羽毛」（树精掉落，概率 40%）</li><li>回公会报到，获得弓箭手资格</li></ol><h2 id="各等级段练级点" tabindex="-1">各等级段练级点 <a class="header-anchor" href="#各等级段练级点" aria-label="Permalink to &quot;各等级段练级点&quot;">​</a></h2><ul><li><strong>1-20 级</strong>：南门平原（远程开怪，无伤练级）</li><li><strong>21-40 级</strong>：斐杨森林刷树精（二连矢秒杀，效率高）</li><li><strong>41-60 级</strong>：欧克洞窟 1 层刷欧克战士（风筝打法，安全高效）</li><li><strong>61-99 级</strong>：石波区刷石波（闪电冲击群刷，挂机收益高）</li></ul><h2 id="配装思路" tabindex="-1">配装思路 <a class="header-anchor" href="#配装思路" aria-label="Permalink to &quot;配装思路&quot;">​</a></h2><ul><li><strong>武器</strong>：高 ATK 弓，优先暴击属性</li><li><strong>防具</strong>：轻甲/披肩（加回避），远离怪物不需要太高防御</li><li><strong>饰品</strong>：灵巧 &gt; 敏捷 &gt; 暴击</li></ul><h2 id="挂机设置推荐" tabindex="-1">挂机设置推荐 <a class="header-anchor" href="#挂机设置推荐" aria-label="Permalink to &quot;挂机设置推荐&quot;">​</a></h2><ul><li>技能轮：二连矢 → 普攻 → 普攻 → 闪电冲击（群怪时）</li><li>拾取：全部拾取，弓箭手负重足</li><li>补给设置：HP 低于 50% 自动吃红药，SP 低于 30% 自动吃蓝药</li></ul><h2 id="风筝技巧" tabindex="-1">风筝技巧 <a class="header-anchor" href="#风筝技巧" aria-label="Permalink to &quot;风筝技巧&quot;">​</a></h2><p>弓箭手的核心玩法是放风筝：</p><ol><li>起手「冲锋箭」击退怪物</li><li>后退同时普攻</li><li>怪物靠近再次「冲锋箭」</li><li>循环到死，无伤打怪</li></ol>',19)])])}const _=t(o,[["render",s]]);export{u as __pageData,_ as default};
